export interface NumericSequence { kind: 'numeric'; minimum: number; maximum: number; step: number; }
export interface ChoiceSequence { kind: 'choice'; options: readonly string[]; }
export type SequenceSpec = NumericSequence | ChoiceSequence;

type Listener = (value: number | string) => void;
type Subscription = { listener: Listener; owner?: Listener };

export class SequenceChooser {
  private readonly values: Array<number | string>;
  private index = 0;
  private readonly subscriptions: Subscription[] = [];
  private notifying?: Listener;

  constructor(spec: SequenceSpec) {
    if (spec.kind === 'numeric') {
      const { minimum, maximum, step } = spec;
      if (![minimum, maximum, step].every(Number.isFinite) || step <= 0 || minimum > maximum) {
        throw new Error('Invalid numeric sequence');
      }
      this.values = [];
      for (let n = 0; ; n++) {
        const value = minimum + n * step;
        if (value >= maximum) break;
        this.values.push(value);
        const next = minimum + (n + 1) * step;
        if (next <= value) break;
      }
    } else {
      if (spec.options.length === 0 || spec.options.some(option => typeof option !== 'string' || !option.trim())) {
        throw new Error('Invalid choices');
      }
      this.values = [...spec.options];
    }
  }

  next(): number | string {
    const value = this.values[this.index];
    this.index = (this.index + 1) % this.values.length;
    const snapshot = [...this.subscriptions];
    for (const subscription of snapshot) {
      const previous = this.notifying;
      this.notifying = subscription.listener;
      try {
        subscription.listener(value);
      } finally {
        this.notifying = previous;
      }
    }
    return value;
  }

  reset(): void { this.index = 0; }

  subscribe(listener: Listener): () => void {
    const subscription: Subscription = { listener, owner: this.notifying };
    this.subscriptions.push(subscription);
    let active = true;
    return () => {
      if (!active) return;
      active = false;
      const matches = (candidate: Subscription): boolean =>
        candidate === subscription ||
        (subscription.owner !== undefined && candidate.owner === subscription.owner);
      for (let index = this.subscriptions.length - 1; index >= 0; index--) {
        if (matches(this.subscriptions[index])) this.subscriptions.splice(index, 1);
      }
    };
  }
}

