import { SequenceChooser, SequenceSpec } from './solution';

function equal(actual: unknown, expected: unknown, message: string): void { if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`); }
function deepEqual(actual: unknown, expected: unknown, message: string): void { if (JSON.stringify(actual) !== JSON.stringify(expected)) throw new Error(`${message}: ${JSON.stringify(actual)}`); }
function throws(action: () => unknown, message: string): void { let didThrow = false; try { action(); } catch { didThrow = true; } if (!didThrow) throw new Error(message); }

const numericInput: SequenceSpec = { kind: 'numeric', minimum: -1, maximum: 4, step: 2 };
const numeric = new SequenceChooser(numericInput);
(numericInput as { kind: 'numeric'; minimum: number; maximum: number; step: number }).minimum = 100;
deepEqual([numeric.next(), numeric.next(), numeric.next(), numeric.next()], [-1, 1, 3, -1], 'numeric sequence is aligned, cyclic, and copied');
numeric.reset();
equal(numeric.next(), -1, 'reset restarts numeric sequence');

const singleton = new SequenceChooser({ kind: 'numeric', minimum: 5, maximum: 5, step: 3 });
deepEqual([singleton.next(), singleton.next()], [5, 5], 'equal bounds produce one cyclic value');

throws(() => new SequenceChooser({ kind: 'numeric', minimum: NaN, maximum: 1, step: 1 }), 'NaN minimum rejected');
throws(() => new SequenceChooser({ kind: 'numeric', minimum: 0, maximum: Infinity, step: 1 }), 'infinite maximum rejected');
throws(() => new SequenceChooser({ kind: 'numeric', minimum: 0, maximum: 1, step: 0 }), 'zero step rejected');
throws(() => new SequenceChooser({ kind: 'numeric', minimum: 0, maximum: 1, step: -1 }), 'negative step rejected');
throws(() => new SequenceChooser({ kind: 'numeric', minimum: 2, maximum: 1, step: 1 }), 'reversed range rejected');

const options = ['red', 'blue'];
const choice = new SequenceChooser({ kind: 'choice', options });
options[0] = 'mutated';
options.push('green');
deepEqual([choice.next(), choice.next(), choice.next()], ['red', 'blue', 'red'], 'choice input copied and sequence cycles');
choice.reset();
equal(choice.next(), 'red', 'choice reset restarts');
throws(() => new SequenceChooser({ kind: 'choice', options: [] }), 'empty options rejected');
throws(() => new SequenceChooser({ kind: 'choice', options: ['ok', ''] }), 'empty option rejected');
throws(() => new SequenceChooser({ kind: 'choice', options: ['ok', 2 as unknown as string] }), 'non-string option rejected');

const notified = new SequenceChooser({ kind: 'choice', options: ['a', 'b'] });
const events: string[] = [];
let removeSecond: () => void = () => {};
let removeLate: () => void = () => {};
const removeFirst = notified.subscribe(value => {
  events.push(`first:${String(value)}`);
  removeSecond();
  removeLate = notified.subscribe(next => events.push(`late:${String(next)}`));
});
removeSecond = notified.subscribe(value => events.push(`second:${String(value)}`));
equal(notified.next(), 'a', 'next returns first value');
deepEqual(events, ['first:a', 'second:a'], 'next notifies listener snapshot in order');
equal(notified.next(), 'b', 'next advances');
deepEqual(events, ['first:a', 'second:a', 'first:b', 'late:b'], 'listener changes affect later next calls');
removeFirst();
removeFirst();
removeLate();
removeLate();
equal(notified.next(), 'a', 'unsubscribing does not affect cycling');
deepEqual(events, ['first:a', 'second:a', 'first:b', 'late:b'], 'unsubscribe idempotent');

